const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const Q={up:[-0.7071068,0,0,0.7071068],down:[0.7071068,0,0,0.7071068],left:[0,0,0.7071068,0.7071068],right:[0,0,-0.7071068,0.7071068]};
const px=c=>(c-1)*1.1, pz=r=>(1-r)*1.1;
const dist=s=>(2-s.c)+(2-s.r);
export function initialState(){return {c:0,r:0,moves:0,hint:null,msg:''};}
export function reduce({state,event}){
 if(event.type!=='action')return state;
 const s=state, a=event.action;
 if(dist(s)===0)return s;
 if(a==='hint'){const h=s.c<2?'right':'up';return {...s,hint:h,msg:'Try moving '+h+': it brings you one step closer.'};}
 const d=D[a]; if(!d)return s;
 const c=s.c+d[0], r=s.r+d[1];
 if(c<0||c>2||r<0||r>2)return {...s,hint:null,msg:'That move would leave the board.'};
 return {c,r,moves:s.moves+1,hint:null,msg:''};
}
export function evaluate({state}){
 const s=state||initialState();
 const k=dist(s), won=k===0;
 const y=won?0.43:0.35;
 const nodes={tok:{position:[px(s.c),y,pz(s.r)]},hintA:{visible:!!s.hint&&!won,position:[px(s.c),0.35,pz(s.r)]}};
 if(s.hint)nodes.hintA.quaternion=Q[s.hint];
 let msg=s.msg||'Move the token to the orange goal square.';
 if(won)msg='You reached the goal in '+s.moves+' moves (shortest possible: 4).'+(s.moves===4?' Perfect route!':'');
 return {nodes,readouts:{moves:s.moves,dist:k},goal:{status:won?'won':'playing',message:msg}};
}
